use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path,process::Command};
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/lehmer-inverse175");let d=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-lehmer-inverse175");let read=|p:&Path|->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()};let digest=|b:&[u8]|format!("{:x}",Sha256::digest(b));let declared=read(&d.join("artifacts/review.json"));let mut checked=BTreeMap::new();
 for name in["source","caller-source","helpers","receipts"]{
  let p=d.join(format!("artifacts/{name}.json.gz"));let dec=Command::new("gzip").args(["-d","-c"]).arg(&p).output().unwrap();assert!(dec.status.success());let members:Value=serde_json::from_slice(&dec.stdout).unwrap();let members=members.as_object().unwrap();assert_eq!(declared["archive_members"][name],members.len());
  let base=if ["source","caller-source"].contains(&name){r.join(name)}else{r.to_path_buf()};
  for(f,m)in members{let p=Path::new(f);assert!(!p.is_absolute()&&!p.components().any(|c|matches!(c,std::path::Component::ParentDir)));let bytes=m["bytes"].as_array().unwrap().iter().map(|b|u8::try_from(b.as_u64().unwrap()).unwrap()).collect::<Vec<_>>();assert_eq!(digest(&bytes),m["sha256"]);assert_eq!(bytes,fs::read(base.join(p)).unwrap());}
  checked.insert(name,json!({"members":members.len(),"all_member_bytes_and_hashes_match_originals":true,"archive_sha256":digest(&fs::read(p).unwrap())}));
 }
 let a=read(&r.join("analysis.json"));assert_eq!(a,read(&d.join("artifacts/analysis.json")));let rows=fs::read(r.join("accepted-rows.json")).unwrap();assert_eq!(rows,fs::read(d.join("accepted-rows.json")).unwrap());assert_eq!(rows,fs::read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-sdk175/accepted-rows.json").unwrap());
 let review=read(&d.join("artifacts/analysis-repair-review.json"));assert_eq!(review["passed"],true);for(p,h)in review["repair_pins"].as_object().unwrap(){assert_eq!(digest(&fs::read(p).unwrap()),h.as_str().unwrap());}
 let manifest=read(Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json"));for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(digest(&fs::read(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)).unwrap()),h.as_str().unwrap());}
 let md=fs::read_to_string(d.join("README.md")).unwrap();let mut links=0;let mut tail=md.as_str();while let Some(i)=tail.find("]("){tail=&tail[i+2..];let Some(j)=tail.find(')')else{break};let path=tail[..j].split('#').next().unwrap();if !path.starts_with("http")&&!path.is_empty(){assert!(d.join(path).exists(),"missing link {path}");links+=1;}tail=&tail[j+1..];}
 fs::write(d.join("artifacts/post-publication-review.json"),serde_json::to_vec_pretty(&json!({"passed":true,"archives":checked,"all175production_files_unchanged":true,"all9accepted_local_AWS_rows_and_CPU_Metal_references_exact":true,"fixed_period_repair_pins_verified":true,"local_readme_links_checked":links,"component_gate":a["component_gate"],"performance_or_native_test_reruns":0,"SDK_requests":0,"new_Gnark_exports":0,"proof_ledger_unchanged":26203})).unwrap()).unwrap();println!("All4archives/memberbytes/repairpins/175productionfiles/accepted9rows/{links}links PASS");
}
